BEGIN;
CREATE TABLE IF NOT EXISTS close_checklist_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),template_name varchar(255) NOT NULL,industry varchar(100),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS close_checklist_template_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),template_id uuid NOT NULL REFERENCES close_checklist_templates(id) ON DELETE CASCADE,task_name varchar(255) NOT NULL,category varchar(100) NOT NULL,task_order integer NOT NULL,required boolean NOT NULL DEFAULT true,estimated_hours numeric(7,2),UNIQUE(template_id,task_order));
CREATE TABLE IF NOT EXISTS close_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_id uuid NOT NULL REFERENCES entities(id),accounting_period_id uuid REFERENCES accounting_periods(id),month smallint NOT NULL CHECK(month BETWEEN 1 AND 12),year smallint NOT NULL,status varchar(25) NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','IN_PROGRESS','READY_FOR_REVIEW','CLOSED','LOCKED')),close_percentage numeric(5,2) NOT NULL DEFAULT 0 CHECK(close_percentage BETWEEN 0 AND 100),closed_by uuid REFERENCES users(id),closed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(entity_id,month,year));
CREATE TABLE IF NOT EXISTS close_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),close_period_id uuid NOT NULL REFERENCES close_periods(id) ON DELETE CASCADE,template_task_id uuid REFERENCES close_checklist_template_tasks(id),task_name varchar(255) NOT NULL,category varchar(100) NOT NULL,assigned_to uuid REFERENCES users(id),reviewer_id uuid REFERENCES users(id),due_date date,status varchar(25) NOT NULL DEFAULT 'NOT_STARTED' CHECK(status IN ('NOT_STARTED','IN_PROGRESS','READY_FOR_REVIEW','COMPLETED','LATE','REJECTED')),notes text,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS close_task_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid NOT NULL REFERENCES close_tasks(id) ON DELETE CASCADE,document_id uuid NOT NULL REFERENCES documents(id),uploaded_by uuid REFERENCES users(id),uploaded_at timestamptz NOT NULL DEFAULT now(),UNIQUE(task_id,document_id));
CREATE INDEX IF NOT EXISTS ix_close_tasks_period_status ON close_tasks(close_period_id,status,due_date);
COMMIT;
